"""
    Gets two lists and returns set difference of the two lists.
    But if one of them is None (file loading error) then the return value is None
    """
def compare_two_data_lists(data1: Any, data2: Any) -> object {
    set_difference = None;
    if ((data1 is None) or (data2 is None)) {
        set_difference = None;
    } else {
        set_difference = len(`set(data1).difference(data2));
    }
    return set_difference;
}

"""
        Energy Consumption
        Notes
        ------
            Energy consumption for different time periods
    """
def calc_energy_consumption(
    hvac_kwh_per_day: Any, lights_kwh_per_day: Any, misc_kwh_per_day: Any
) -> object {
    farm_kwh_per_day = hvac_kwh_per_day + lights_kwh_per_day + misc_kwh_per_day;
    farm_kwh_per_week = farm_kwh_per_day * 7;
    farm_kwh_per_month = farm_kwh_per_day * 30.417;
    farm_kwh_per_year = farm_kwh_per_day * 365;
    return (farm_kwh_per_day, farm_kwh_per_week, farm_kwh_per_month, farm_kwh_per_year);
}

"""
    Wraps the value with Terraform interpolation syntax.

    Usage: "{{ 'module.example.arn' | tf }}"
    Output: "${module.example.arn}"

    """
def tf(value: Any) -> object {
    return ('${' + value + '}');
}
